import{_ as a,o as r,c as t,a2 as o}from"./chunks/framework.doxMM-x8.js";const h=JSON.parse('{"title":"Module boundaries","description":"","frontmatter":{"docLocale":"en","counterpart":"/architecture/module-boundaries","contentType":"concept","prev":{"text":"Project structure","link":"/en/architecture/project-structure"},"next":false},"headers":[],"relativePath":"en/architecture/module-boundaries.md","filePath":"en/architecture/module-boundaries.md"}'),s={name:"en/architecture/module-boundaries.md"};function n(i,e,c,b,d,l){return r(),t("div",null,[...e[0]||(e[0]=[o(`<h1 id="module-boundaries" tabindex="-1">Module boundaries <a class="header-anchor" href="#module-boundaries" aria-label="Permalink to &quot;Module boundaries&quot;">​</a></h1><p>Lab owns laboratory behavior. Platform Core owns identity, members, keys, files, audit, idempotency and limits. Core does not import Lab. The Node application composes them through public capabilities, as recorded in <a href="https://github.com/CaiZongyuan/labworld/blob/5bc2e40dbe78e853bcab2fd1c986ac39edee52b4/docs/adr/0010-single-typescript-lab-word-server.md" target="_blank" rel="noreferrer">ADR 0010</a> and <a href="https://github.com/CaiZongyuan/labworld/blob/5bc2e40dbe78e853bcab2fd1c986ac39edee52b4/docs/adr/0011-pglite-embedded-database.md" target="_blank" rel="noreferrer">ADR 0011</a>.</p><p>The <a href="https://github.com/CaiZongyuan/labworld/blob/5bc2e40dbe78e853bcab2fd1c986ac39edee52b4/apps/web/src/app.ts" target="_blank" rel="noreferrer">application entry</a> supplies Lab&#39;s routes, navigation and messages to the shared shell. The <a href="https://github.com/CaiZongyuan/labworld/blob/5bc2e40dbe78e853bcab2fd1c986ac39edee52b4/apps/web/src/router.tsx" target="_blank" rel="noreferrer">router</a> owns TanStack types and browser navigation. Heavy views stay lazy. Web consumes generated SDK/DTOs; database code does not enter its bundle.</p><p>The <a href="https://github.com/CaiZongyuan/labworld/blob/5bc2e40dbe78e853bcab2fd1c986ac39edee52b4/apps/server/src/runtime.ts" target="_blank" rel="noreferrer">runtime</a> composes service owners. Database drivers and migration execution belong only to platform/db. Pure domains cannot import infrastructure. Business use cases own transactions; Core audit and idempotency commit with the same business operation.</p><p><a href="https://github.com/CaiZongyuan/labworld/blob/5bc2e40dbe78e853bcab2fd1c986ac39edee52b4/packages/server/src/lab/world/schema.ts" target="_blank" rel="noreferrer">Node schema declarations</a> own qualified tables. <a href="https://github.com/CaiZongyuan/labworld/blob/5bc2e40dbe78e853bcab2fd1c986ac39edee52b4/packages/server/src/lab/ownership.json" target="_blank" rel="noreferrer">Lab ownership</a> records its Views path, exact SDK helper paths and contract symbols. <a href="https://github.com/CaiZongyuan/labworld/blob/5bc2e40dbe78e853bcab2fd1c986ac39edee52b4/scripts/check-boundaries.mjs" target="_blank" rel="noreferrer">Boundary checks</a> validate package imports, Node table declarations/migrations and the SDK/Core restrictions. <a href="https://github.com/CaiZongyuan/labworld/blob/5bc2e40dbe78e853bcab2fd1c986ac39edee52b4/scripts/lib/server-boundaries.mjs" target="_blank" rel="noreferrer">Server checks</a> follow transitive Core/domain dependencies. Static checks do not prove authorization, dynamic SQL or recovery.</p><p>Lab Views own overview <a href="https://github.com/CaiZongyuan/labworld/blob/5bc2e40dbe78e853bcab2fd1c986ac39edee52b4/packages/views/src/lab/operations-state.ts" target="_blank" rel="noreferrer">summaries and registered regions</a> and the <a href="https://github.com/CaiZongyuan/labworld/blob/5bc2e40dbe78e853bcab2fd1c986ac39edee52b4/packages/views/src/lab/operations-view.tsx" target="_blank" rel="noreferrer">device view</a>. They read existing World, property observations, trends, and records. They add no identity or service. The shared workbench owns one World subscription, layout drafts, and device operation attempts. Core and the general shell do not calculate these business facts.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> boundaries:check</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> typecheck</span></span></code></pre></div><p>Run from the repository root. Use HTTP/browser and controlled ownership checks for behavior. See <a href="https://github.com/CaiZongyuan/labworld/blob/5bc2e40dbe78e853bcab2fd1c986ac39edee52b4/docs/testing/strategy.md" target="_blank" rel="noreferrer">testing</a> and <a href="./lab-word">product scope</a>. Historical static-example architecture remains recorded in earlier ADRs; it is not an active removal or composition framework.</p><hr><p>Source version：<code>5bc2e40dbe78</code> · <a href="https://github.com/CaiZongyuan/labworld/blob/5bc2e40dbe78e853bcab2fd1c986ac39edee52b4/docs/architecture/module-boundaries.en.md" target="_blank" rel="noreferrer">Page Markdown</a></p>`,10)])])}const u=a(s,[["render",n]]);export{h as __pageData,u as default};
